+/* Experimental Q8 output head with one argmax partial per two rows.
+ * Keep the dense kernel's eight-SIMD-group K walk and reduction tree. */
+struct qwen4_head_args { uint in_dim, n_vocab; };
+kernel void kernel_qwen4_head_argmax(
+        constant qwen4_head_args &args,
+        device const block_q8_0 *weights,
+        device const float *x,
+        device uint2 *partials,
+        device float *logits,
+        uint group [[threadgroup_position_in_grid]],
+        ushort lane [[thread_index_in_simdgroup]],
+        ushort sg [[simdgroup_index_in_threadgroup]]) {
+    const uint r0 = group * 16u;
+    const uint nb = args.in_dim / 32u;
+    float sums[16] = {0.f};
+    const short ix = lane / 4, il = lane % 4;
+    for (uint ib = sg * 8u + ix; ib < nb; ib += 64u) {
+        float yl[8];
+        for (short i = 0; i < 8; ++i) yl[i] = x[ib * 32u + il * 8 + i];
+        for (short row = 0; row < 16; ++row) {
+            if (r0 + row >= args.n_vocab) continue;
+            device const block_q8_0 &b = weights[(ulong)(r0 + row) * nb + ib];
+            float sumq = 0.f;
+            FOR_UNROLL (short i = 0; i < 8; ++i) sumq += b.qs[il * 8 + i] * yl[i];
+            sums[row] += sumq * b.d;
+        }
+    }
+    threadgroup float shared[512];
+    for (short row = 0; row < 16; ++row) {
+        if (!sg) shared[row * 32 + lane] = 0.f;
+        sums[row] = simd_sum(sums[row]);
+    }
+    threadgroup_barrier(mem_flags::mem_threadgroup);
+    for (short row = 0; row < 16; ++row) if (!lane) shared[row * 32 + sg] = sums[row];
+    threadgroup_barrier(mem_flags::mem_threadgroup);
+    float best = -1.e30f;
+    uint index = 0;
+    for (short row = 0; row < 16; ++row) {
+        float v = simd_sum(shared[row * 32 + lane]);
+        if (r0 + row >= args.n_vocab) continue;
+        if ((as_type<uint>(v) & 0x7fffffffu) > 0x7f800000u) continue;
+        if (v > best || (v == best && r0 + row < index)) { best = v; index = r0 + row; }
+    }
+    if (!sg && !lane) partials[group] = uint2(as_type<uint>(best), index);
+}
